import { test, expect } from '@playwright/test';

test.describe('Form Submission with Stale Data Invalidation', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/form');
  });

  test('should invalidate stale data after successful form submission', async ({ page }) => {
    // Setup: Fill form with stale data
    const nameInput = page.getByLabel('Full Name');
    await nameInput.fill('John Doe');

    const emailInput = page.getByLabel('Email Address');
    await emailInput.fill('john.doe@example.com');

    const submitButton = page.getByRole('button', { name: /submit/i });
    await submitButton.click();

    // Verify initial stale data is displayed
    const nameDisplay = page.getByText('John Doe');
    await expect(nameDisplay).toBeVisible();

    const emailDisplay = page.getByText('john.doe@example.com');
    await expect(emailDisplay).toBeVisible();

    // Wait for API response
    const responsePromise = page.waitForResponse(response =>
      response.url().includes('/api/form-submission') && response.status() === 200
    );

    await responsePromise;

    // Verify success message
    const successMessage = page.getByText('Form submitted successfully');
    await expect(successMessage).toBeVisible();

    // Verify data is no longer stale
    const updatedNameDisplay = page.getByText('Jane Smith');
    await expect(updatedNameDisplay).toBeVisible();

    const updatedEmailDisplay = page.getByText('jane.smith@example.com');
    await expect(updatedEmailDisplay).toBeVisible();

    // Verify error message is not displayed
    const errorMessage = page.getByText('Error');
    await expect(errorMessage).not.toBeVisible();
  });

  test('should handle failed form submission and retain stale data', async ({ page }) => {
    // Setup: Fill form with stale data
    const nameInput = page.getByLabel('Full Name');
    await nameInput.fill('John Doe');

    const emailInput = page.getByLabel('Email Address');
    await emailInput.fill('john.doe@example.com');

    const submitButton = page.getByRole('button', { name: /submit/i });
    await submitButton.click();

    // Verify initial stale data is displayed
    const nameDisplay = page.getByText('John Doe');
    await expect(nameDisplay).toBeVisible();

    const emailDisplay = page.getByText('john.doe@example.com');
    await expect(emailDisplay).toBeVisible();

    // Simulate failed API response
    await page.route('**/api/form-submission', route => {
      route.abort('Failed to process form');
    });

    // Verify error message is displayed
    const errorMessage = page.getByText('Error submitting form');
    await expect(errorMessage).toBeVisible();

    // Verify stale data is still displayed
    await expect(nameDisplay).toBeVisible();
    await expect(emailDisplay).toBeVisible();

    // Verify form is still visible and editable
    const formContainer = page.locator('[data-testid="form-container"]');
    await expect(formContainer).toBeVisible();

    const nameInput = page.getByLabel('Full Name');
    await expect(nameInput).toBeVisible();

    const emailInput = page.getByLabel('Email Address');
    await expect(emailInput).toBeVisible();

    // Verify form is still editable
    await nameInput.fill('John Doe');
    await emailInput.fill('john.doe@example.com');

    // Verify form is still visible
    await expect(formContainer).toBeVisible();
  });
});
